('침신사랑장학금', '한국침례신학대학교', '동일 교회에서 신입생 3명 이상이 동시에 입학할 경우, 담임목사 추천을 받은 1명에게 지급. 수업료 100%. 제출서류: 교회주보, 재직증명서, 목회자추천서.', NULL, 'http://www.kbtus.ac.kr/kor/CMS/Contents/Contents.do?mCode=MN303', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '신입학 시 선발 (한국침례신학대학교 입학처/학생지원팀 공지 확인)', '한국침례신학대학교', NULL, NULL, 1, 1, NULL, 'school_internal', 'special_target'),
('침례교사모장학금', '한국침례신학대학교', '침례교단 인준 목회자의 배우자(사모) 대상. 수업료 13% 지원. 제출서류: 재직증명서, 가족관계증명서.', NULL, 'http://www.kbtus.ac.kr/kor/CMS/Contents/Contents.do?mCode=MN303', NULL, NULL, NULL, NULL, NULL, NULL, 2.5, 'semester', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 말 시험기간 중 신청 (장학금지급규정 제8조: 예배출석 P등급·직전학기 평점평균 2.5 이상·과락 없음)', '한국침례신학대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'special_target'),
('목회자(자녀)장학금(침례신학대)', '한국침례신학대학교', '침례교단 또는 타 교단 인준 목회자의 자녀(만 33세 미만) 대상. 수업료 30% 지원. 1개 학위과정에 한해 지급.', NULL, 'http://www.kbtus.ac.kr/kor/CMS/Contents/Contents.do?mCode=MN303', NULL, 33, NULL, NULL, NULL, NULL, 2.5, 'semester', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 말 시험기간 중 신청 (장학금지급규정 제8조 공통기준 적용)', '한국침례신학대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'special_target'),
('해외선교사(자녀)장학금(침례신학대)', '한국침례신학대학교', '한국침례회 해외선교회 소속 장기선교사(북한 선교사 포함)의 자녀 대상. 수업료 50% 지원.', NULL, 'http://www.kbtus.ac.kr/kor/CMS/Contents/Contents.do?mCode=MN303', NULL, NULL, NULL, NULL, NULL, NULL, 2.5, 'semester', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 말 시험기간 중 신청 (장학금지급규정 제8조 공통기준 적용)', '한국침례신학대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'special_target'),
('세가족장학금(침례신학대)', '한국침례신학대학교', '직계가족 3인 이상이 학부·대학원에 동시 재학 중인 경우 가족이 지정한 1인에게 지급. 수업료 65%.', NULL, 'http://www.kbtus.ac.kr/kor/CMS/Contents/Contents.do?mCode=MN303', NULL, NULL, NULL, NULL, NULL, NULL, 2.5, 'semester', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 말 시험기간 중 신청 (장학금지급규정 제8조 공통기준 적용)', '한국침례신학대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'special_target'),
('부부장학금(침례신학대)', '한국침례신학대학교', '부부가 동시 재학 중인 경우 지정한 1인에게 지급. 수업료 50%.', NULL, 'http://www.kbtus.ac.kr/kor/CMS/Contents/Contents.do?mCode=MN303', NULL, NULL, NULL, NULL, NULL, NULL, 2.5, 'semester', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 말 시험기간 중 신청 (장학금지급규정 제8조 공통기준 적용)', '한국침례신학대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'special_target'),
('교직원자녀장학금(침례신학대)', '한국침례신학대학교', '한국침례신학대학교 교직원의 자녀(만 33세 미만) 대상. 수업료 100%. 1개 학위과정에 한해 지급.', NULL, 'http://www.kbtus.ac.kr/kor/CMS/Contents/Contents.do?mCode=MN303', NULL, 33, NULL, NULL, NULL, NULL, 2.5, 'semester', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 말 시험기간 중 신청 (장학금지급규정 제8조 공통기준 적용)', '한국침례신학대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'special_target'),
('교직원(배우자)장학금(침례신학대)', '한국침례신학대학교', '한국침례신학대학교 교직원 본인 또는 그 배우자 대상. 수업료 50%. 1개 학위과정에 한해 지급.', NULL, 'http://www.kbtus.ac.kr/kor/CMS/Contents/Contents.do?mCode=MN303', NULL, NULL, NULL, NULL, NULL, NULL, 2.5, 'semester', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 말 시험기간 중 신청 (장학금지급규정 제8조 공통기준 적용)', '한국침례신학대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'special_target'),
('북한이탈주민장학금(침례신학대)', '한국침례신학대학교', '북한이탈주민 재학생 대상(교내 자체 재원). 수업료 50% 지원. 참고: 홈페이지 교외장학금 목록에도 통일부 관련 법령 근거의 동명 국가지원 프로그램이 별도로 안내되어 있으나, 대학 무관 전국공통 성격이라 이번 배치에서는 이 교내 자체 재원 항목만 채택함(중복 방지).', NULL, 'http://www.kbtus.ac.kr/kor/CMS/Contents/Contents.do?mCode=MN303', NULL, NULL, NULL, NULL, NULL, NULL, 2.5, 'semester', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 말 시험기간 중 신청 (장학금지급규정 제8조 공통기준 적용)', '한국침례신학대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'special_target'),
('보훈장학금(침례신학대)', '한국침례신학대학교', '국가유공자 본인 또는 배우자는 수업료 100%, 국가유공자 자녀는 직전학기 성적 백분위 70점 이상인 경우 수업료 50% 지원(교내 자체 재원).', NULL, 'http://www.kbtus.ac.kr/kor/CMS/Contents/Contents.do?mCode=MN303', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '백분위 70점 이상(자녀에 한함, 100점 만점 기준이라 min_gpa로 환산 불가)', NULL, '매 학기 말 시험기간 중 신청 (한국침례신학대학교 학사공지 확인)', '한국침례신학대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'special_target'),
('해외교환학생장학금(침례신학대)', '한국침례신학대학교', '해외 교환학생으로 선발된 학생 대상, 장학위원회 심의로 선발·금액 결정.', NULL, 'http://www.kbtus.ac.kr/kor/CMS/Contents/Contents.do?mCode=MN303', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '수시 공지 (한국침례신학대학교 국제교류 관련 공지 확인)', '한국침례신학대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'international_exchange'),
('국외학생장학금(침례신학대)', '한국침례신학대학교', '외국인 학생 대상(국외 한국인 대상 교육 장학금 미수혜자에 한함). 수업료 40% 지원, 최대 2개 학위과정까지 지급. 제출서류: 여권, 목회자추천서, 건강보험 가입증명.', NULL, 'http://www.kbtus.ac.kr/kor/CMS/Contents/Contents.do?mCode=MN303', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'foreigner_only', NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 말 시험기간 중 신청 (한국침례신학대학교 학사공지 확인)', '한국침례신학대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'special_target'),
('침신곰두리장학금', '한국침례신학대학교', '중증장애 학부 재학생 대상. 수업료 50% 지원. 최대 8명 이내 선발, 1개 학위과정에 한해 지급.', NULL, 'http://www.kbtus.ac.kr/kor/CMS/Contents/Contents.do?mCode=MN303', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, NULL, NULL, NULL, NULL, NULL, NULL, '8명 이내', '매 학기 말 시험기간 중 신청 (한국침례신학대학교 학사공지 확인)', '한국침례신학대학교', NULL, 'undergrad_enrolled', NULL, NULL, NULL, 'school_internal', 'special_target'),
('전공실기장학금(침례신학대)', '한국침례신학대학교', '교회음악과 학생 중 학과 교수 추천을 받은 자 대상. 수업료 100% 지원.', NULL, 'http://www.kbtus.ac.kr/kor/CMS/Contents/Contents.do?mCode=MN303', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '교회음악과', NULL, NULL, NULL, NULL, '매 학기 말 시험기간 중 신청 (한국침례신학대학교 학사공지 확인)', '한국침례신학대학교', '교회음악과', NULL, NULL, NULL, NULL, 'school_internal', 'activity_merit'),
