('학생임원장학금 A(침례신학대)', '한국침례신학대학교', '총학생회장·부회장·총무 등 최상위 학생자치기구 임원 대상. 수업료 100% 지원.', NULL, 'http://www.kbtus.ac.kr/kor/CMS/Contents/Contents.do?mCode=MN303', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 말 시험기간 중 신청 (한국침례신학대학교 학사공지 확인)', '한국침례신학대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'activity_merit'),
