('학생임원장학금 C(침례신학대)', '한국침례신학대학교', '학생회 국장·학과 총무 등 실무진 학생자치기구 임원 대상. 수업료 30% 지원.', NULL, 'http://www.kbtus.ac.kr/kor/CMS/Contents/Contents.do?mCode=MN303', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '매 학기 말 시험기간 중 신청 (한국침례신학대학교 학사공지 확인)', '한국침례신학대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'activity_merit'),
('교수학습지원장학금(침례신학대)', '한국침례신학대학교', '교수학습지원센터의 추천을 받은 학생 대상(각종 대회 격려 포함). 지급액은 프로그램별로 상이.', NULL, 'http://www.kbtus.ac.kr/kor/CMS/Contents/Contents.do?mCode=MN303', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '수시 공지 (한국침례신학대학교 교수학습지원센터 공지 확인)', '한국침례신학대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'activity_merit'),
('취창업지원장학금(침례신학대)', '한국침례신학대학교', '진로·취업지원센터의 추천을 받은 학생 대상(각종 대회 격려 포함). 지급액은 프로그램별로 상이.', NULL, 'http://www.kbtus.ac.kr/kor/CMS/Contents/Contents.do?mCode=MN303', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '수시 공지 (한국침례신학대학교 진로·취업지원센터 공지 확인)', '한국침례신학대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'activity_merit'),
('대회참가 격려장학금(침례신학대)', '한국침례신학대학교', '각종 대회·경연 참가자 중 소속 학과 추천을 받은 학생 대상. 지급액은 대회별로 상이.', NULL, 'http://www.kbtus.ac.kr/kor/CMS/Contents/Contents.do?mCode=MN303', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '수시 공지 (한국침례신학대학교 학사공지 확인)', '한국침례신학대학교', NULL, NULL, NULL, NULL, NULL, 'school_internal', 'activity_merit'),
